const response = $input.first().json;
const request = $('샘플 입력').first().json;
const texts = typeof request.input === 'string' ? [request.input] : request.input;
const dimensions = request.dimensions ?? 768;
if (response.model !== request.model || response.dimensions !== dimensions || !Array.isArray(response.data) || response.data.length !== texts.length) {
  throw new Error('임베딩 모델·차원·결과 개수가 일치하지 않습니다.');
}
const seen = new Set();
const result = response.data.map(item => {
  if (!Number.isInteger(item.index) || item.index < 0 || item.index >= texts.length || seen.has(item.index) ||
      !Array.isArray(item.embedding) || item.embedding.length !== dimensions ||
      item.embedding.some(value => typeof value !== 'number' || !Number.isFinite(value))) {
    throw new Error('임베딩 index·차원·좌표가 올바르지 않습니다.');
  }
  seen.add(item.index);
  return {json: {index: item.index, text: texts[item.index], model: response.model, dimensions, embedding: item.embedding}};
});
return result.sort((a,b) => a.json.index - b.json.index);
